const b = $input.first().json.body || $input.first().json;
const seed = [...(b.query || 'area')].reduce((h, c) => h + c.charCodeAt(0), 0);
const rnd = (seed % 100) / 100;
const score = Math.round(58 + rnd * 32);
const rec = score >= 78 ? 'pursue' : score >= 62 ? 'watch' : 'pass';
return [{ json: { runId: b.runId, callbackUrl: b.callbackUrl, result: {
  title: b.query,
  subtitle: 'n8n submarket snapshot · Tampa Bay',
  investorScore: score,
  recommendation: rec,
  summary: `${b.query} investor score ${score}. Replace this node with Census / BLS / FEMA HTTP requests.`,
  metrics: [
    { label: 'Investor score', value: String(score) },
    { label: 'YoY price (stub)', value: (2 + rnd * 6).toFixed(1) + '%' },
    { label: 'Vacancy (stub)', value: (3 + rnd * 4).toFixed(1) + '%' }
  ],
  sections: [{ heading: 'Enrichment', body: 'Point this workflow at ACS, FRED, and county GIS. RIP stores whatever you post back in result.' }]
} } }];
